          warehouseStatus={warehouseStatus}
          onOpenAsset={vi.fn()}
        />,
      );
    }

    // The defect: ONE info Alert covered both states, so "last refresh FAILED" —
    // an operational breakage — rendered at the same weight as "answers at a
    // coarser tier". Severity is carried by the antd alert class, so assert on it
    // rather than on wording, which can drift.
    it('renders a FAILED refresh as a warning, not an info note', () => {
      renderWith([warehouse({ last_error: 'The run failed to execute.' })]);
      const alert = screen.getByText(/Warehouse lineage refresh is failing/).closest('.ant-alert');
      expect(alert).toHaveClass('ant-alert-warning');
      expect(screen.getByText(/The run failed to execute\./)).toBeInTheDocument();
    });

    it('renders a degraded tier as an info note', () => {
      renderWith([warehouse({ degraded_reason: 'view-level only (Enterprise needed)' })]);
      const alert = screen.getByText(/Workspace lineage sources/).closest('.ant-alert');
      expect(alert).toHaveClass('ant-alert-info');
    });

    // The whole point of the split: when both exist, a failing source must be
    // visually distinct from a degraded one rather than merged into one box.
    it('separates a failing source from a degraded one when both are present', () => {
      renderWith([
        warehouse({ connection_id: 'w1', name: 'Failing SF', last_error: 'auth expired' }),
        warehouse({ connection_id: 'w2', name: 'Coarse SF', degraded_reason: 'view-level only' }),
      ]);
      const failing = screen.getByText(/refresh is failing/).closest('.ant-alert');
      const degraded = screen.getByText(/Workspace lineage sources/).closest('.ant-alert');
      expect(failing).toHaveClass('ant-alert-warning');
      expect(degraded).toHaveClass('ant-alert-info');
      expect(failing).not.toBe(degraded);
      // Each source appears under its own advisory, not both under one.
      expect(failing).toHaveTextContent('Failing SF');
      expect(failing).not.toHaveTextContent('Coarse SF');
      expect(degraded).toHaveTextContent('Coarse SF');
      expect(degraded).not.toHaveTextContent('Failing SF');
    });

    // #916: the advisory is workspace-wide by design (a tier is a property of the
    // SOURCE, not the asset), so a pure-UC asset legitimately lists Snowflake
    // connections. The framing has to say so or it reads as a bug.
    it('frames the degraded advisory as workspace-level, not asset-scoped', () => {
      renderWith([warehouse({ degraded_reason: 'view-level only' })]);
      expect(screen.getByText(/Workspace lineage sources/)).toBeInTheDocument();
      expect(
        screen.getByText(/workspace-wide source qualifiers, not findings about this asset/),
      ).toBeInTheDocument();
    });

    it('shows neither advisory when every source is healthy', () => {
      renderWith([warehouse()]);
      expect(screen.queryByText(/refresh is failing/)).not.toBeInTheDocument();
      expect(screen.queryByText(/Workspace lineage sources/)).not.toBeInTheDocument();
    });
  });
});

