15	
16	/**
17	 * Lineage graph (#805) — one left-to-right DAG replacing the two separate
18	 * upstream/downstream list boxes: provenance on the left, the asset under view in
19	 * the middle, blast radius on the right, one column per hop.
20	 *
21	 * Nodes are clickable and navigate to that asset. Depth ≥2 comes for free from the
22	 * existing blast-radius BFS, which now also hands back each node's hop depth and
23	 * the real edges between them — so a depth-2 node is drawn hanging off the node it
24	 * actually descends from.
25	 *
26	 * Plain inline SVG, no graph library: the layout is a layered DAG we place
27	 * ourselves (`lineageLayout.ts`), and an SVG in an `overflow-x` container scrolls
28	 * horizontally inside the card on a phone without ever widening the page — which a
29	 * pan/zoom canvas makes harder, not easier. It also keeps the dependency count
30	 * (and the ADR 0031 licence surface) at zero.
31	 */
32	export function LineageGraph({
33	  center,
34	  upstream,
35	  downstream,
36	  edges,
37	  failingSources = [],
38	  warehouseStatus = [],
39	  onOpenAsset,
40	}: {
41	  center: CenterAsset;
42	  upstream: LineageNode[];
43	  downstream: LineageNode[];
44	  edges: LineageEdge[];
45	  /** Lineage-feeding connections whose poll is failing (#828). Non-empty ⇒ what's
46	   *  below may be stale or missing for reasons unrelated to this asset. */
47	  failingSources?: LineageSourceHealth[];
48	  /** Warehouse-native lineage sources that are degraded (coarser tier) or failing
49	   *  (#858). A degraded source is working but coarse (view-level only), so the graph
50	   *  is real but incomplete — an INFO note, distinct from the failing-source warning. */
51	  warehouseStatus?: WarehouseLineageStatus[];
52	  onOpenAsset: (assetId: string) => void;
53	}) {
54	  const layout = useMemo(
55	    () => buildLineageLayout(center, upstream, downstream, edges),
56	    [center, upstream, downstream, edges],
57	  );
58	  const isolated = upstream.length === 0 && downstream.length === 0;
59	
60	  return (
61	    <Card
62	      size="small"
63	      title={
64	        <Flex gap={8} align="center">
65	          <ApartmentOutlined />
66	          Lineage
67	        </Flex>
68	      }
69	      extra={
70	        !isolated && (
71	          <Typography.Text type="secondary" style={{ fontSize: 12 }}>
72	            {upstream.length} upstream · {downstream.length} downstream
73	          </Typography.Text>
74	        )
75	      }
76	    >
77	      {/* Never show a clean empty state over a broken integration (#828). Prod lineage
78	          was dark for six days behind an expired credential and this card cheerfully
79	          said "No lineage recorded" — indistinguishable from an asset that genuinely
80	          has no upstreams. If a lineage source is failing, say so FIRST, and say it
81	          whether the graph is empty or not (a partial graph is just as misleading). */}
82	      {failingSources.length > 0 && (
83	        <Alert
84	          type="warning"
85	          showIcon
86	          style={{ marginBottom: 12 }}
87	          message="Lineage may be incomplete — a source is failing"
88	          description={
89	            <>
90	              {failingSources.map((s) => (
91	                <div key={s.connection_id}>
92	                  <Typography.Text strong>{s.name}</Typography.Text> ({s.type}) has failed{' '}
93	                  {s.consecutive_failures}{' '}
94	                  {s.consecutive_failures === 1 ? 'poll' : 'consecutive polls'}
95	                  {s.last_error ? `: ${s.last_error}` : '.'}
96	                </div>
97	              ))}
98	              <div style={{ marginTop: 4 }}>
99	                Until it recovers, lineage here may be stale or missing — this is not necessarily
100	                the whole picture.
101	              </div>
102	            </>
103	          }
104	        />
105	      )}
106	      {/* Warehouse-native lineage that is working but COARSE (a degraded tier — e.g.
107	          Snowflake view-level-only because the account isn't Enterprise) or stale. Info,
108	          not warning: the graph is real, just not the richest possible. Never let a
109	          view-level graph read as a confident complete one (#828, #858). */}
110	      {warehouseStatus.length > 0 && (
111	        <Alert
112	          type="info"
113	          showIcon
114	          style={{ marginBottom: 12 }}
115	          message="Warehouse lineage may be coarse or stale"
116	          description={
117	            <>
118	              {warehouseStatus.map((s) => (
119	                <div key={s.connection_id}>
120	                  <Typography.Text strong>{s.name}</Typography.Text> ({s.type}):{' '}
121	                  {s.last_error
122	                    ? `last refresh failed — ${s.last_error}`
123	                    : (s.degraded_reason ?? 'lineage is degraded')}
124	                </div>
125	              ))}
126	            </>
127	          }
128	        />
129	      )}
130	      {/* An asset with no neighbours still renders AS A GRAPH — just its own box, alone.
131	          The old `<Empty>` placeholder replaced the asset with a grey icon, which reads as
132	          "there is nothing here" when the truth is "here is the asset, and nothing is
