def _reject_unknown_filter(name: str, value: str | None, allowed: tuple[str, ...]) -> None:
    """422 on a filter value outside its closed vocabulary (#306).

    An unrecognised `provider`/`env` used to flow straight into the `WHERE`, so a
    typo returned `200 []` — indistinguishable from "this provider genuinely has no
    runs". That is the confidently-empty-response class (#828): the caller reads a
    real answer where there was a mistake. `None` (filter omitted) still means
    "no filter" and is left alone.
    """
    if value is not None and value not in allowed:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
            detail={
                "code": "invalid_filter",
                "message": f"invalid {name} {value!r}",
                "detail": {"allowed": list(allowed)},
