import { MoreOutlined } from '@ant-design/icons';
import {
  App,
  Badge,
  Button,
  Card,
  Divider,
  Dropdown,
  Empty,
  Flex,
  Spin,
  Tag,
  Tooltip,
  Typography,
} from 'antd';
import { useCallback, useState } from 'react';
import { useNavigate } from 'react-router-dom';

import {
  CONNECTION_KIND,
  CONNECTION_KIND_LABELS,
  CONNECTION_KINDS,
  CONNECTION_TYPE_LABELS,
  type Connection,
  deleteConnection,
  ENV_COLORS,
  envLabel,
  listConnections,
  testConnection,
} from '../api/connections';
import { ConnectionTypeAvatar } from '../components/connections/connectionVisuals';
import { ReauthModal } from '../components/connections/ReauthModal';
import { Page } from '../components/layout/Page';
import { type AsyncState, useAsyncData } from '../hooks/useAsyncData';
import { useConfirmDelete } from '../hooks/useConfirmDelete';
import { PageError } from '../components/feedback/PageError';

/** Live connectivity state for a card — the health-page badge. */
type HealthState = 'idle' | 'testing' | 'ok' | 'failed';

/** Per-card actions, threaded from the page so they can mutate shared state. */
interface ConnectionActions {
  onEdit: (connection: Connection) => void;
  onReauth: (connection: Connection) => void;
  onChanged: () => void;
  /** Run a connectivity test and reflect the result on the card's health badge. */
  onTest: (connection: Connection) => Promise<boolean>;
  /** Drop a connection's stale health entry (after delete / edit / re-auth). */
  onClearHealth: (id: string) => void;
}

export function Connections() {
  const { message } = App.useApp();
  const navigate = useNavigate();
  const { state, reload } = useAsyncData(listConnections);
  const [reauthing, setReauthing] = useState<Connection | null>(null);
  // Per-connection live connectivity status (the bulk health view).
  const [health, setHealth] = useState<Record<string, HealthState>>({});
  const [testingAll, setTestingAll] = useState(false);

  const testOne = useCallback(async (connection: Connection): Promise<boolean> => {
    setHealth((h) => ({ ...h, [connection.id]: 'testing' }));
    try {
      const { ok } = await testConnection(connection.id);
      setHealth((h) => ({ ...h, [connection.id]: ok ? 'ok' : 'failed' }));
      return ok;
    } catch {
      setHealth((h) => ({ ...h, [connection.id]: 'failed' }));
      return false;
    }
  }, []);

  // Drop a stale health result when the connection changes underneath it —
  // after a re-auth, an edit, or a delete the prior pass/fail no longer holds,
  // so the badge returns to idle until re-tested (and the map can't leak).
  const clearHealth = useCallback((id: string) => {
    setHealth((h) =>
      id in h ? Object.fromEntries(Object.entries(h).filter(([key]) => key !== id)) : h,
    );
  }, []);

  const connections = state.status === 'ok' ? state.data : [];

  const testAll = async () => {
    setTestingAll(true);
    const results = await Promise.all(connections.map(testOne));
    setTestingAll(false);
    const failed = results.filter((ok) => !ok).length;
    if (failed === 0) message.success(`All ${results.length} connections healthy`);
    else message.warning(`${failed} of ${results.length} connections unreachable`);
  };

  const actions: ConnectionActions = {
    // Editing is a dedicated page (create + edit pages replace the drawer, ADR 0022).
    onEdit: (connection) => navigate(`/connections/${connection.id}/edit`),
    onReauth: setReauthing,
    onChanged: reload,
    onTest: testOne,
    onClearHealth: clearHealth,
  };

  return (
    <Page>
      <Flex justify="space-between" align="center" gap={12} wrap>
        <Typography.Title level={3} style={{ margin: 0 }}>
          Connections
        </Typography.Title>
        <Flex gap={8}>
          <Button loading={testingAll} disabled={connections.length === 0} onClick={testAll}>
            Test all
          </Button>
          <Button type="primary" onClick={() => navigate('/connections/new')}>
            Add connection
          </Button>
        </Flex>
      </Flex>
      <ConnectionsBody state={state} actions={actions} health={health} />
      <ReauthModal
        connection={reauthing}
        onClose={() => setReauthing(null)}
        onDone={() => {
          // Credential rotated → the old unreachable verdict no longer holds.
          if (reauthing) clearHealth(reauthing.id);
          setReauthing(null);
          reload();
        }}
      />
    </Page>
  );
}

function ConnectionsBody({
  state,
  actions,
  health,
}: {
  state: AsyncState<Connection[]>;
  actions: ConnectionActions;
  health: Record<string, HealthState>;
}) {
  if (state.status === 'loading') {
    return <Spin description="Loading connections…" size="large" style={{ marginTop: 80 }} />;
  }
  if (state.status === 'error') {
    return (
      <PageError
        error={state.error}
        kind={state.kind}
        httpStatus={state.httpStatus}
        requestId={state.requestId}
      />
    );
  }
  const connections = state.data;
  if (connections.length === 0) {
    return <Empty description="No connections configured yet" />;
  }
  // Two top-level sections (Data sources / Orchestration) — the load-bearing
  // distinction in DataQ (CLAUDE.md §4). Each renders as one even card grid (the
  // per-type avatar already identifies the source), so cards stay large and
  // evenly spaced rather than fragmenting into ragged per-type rows.
  const sections = CONNECTION_KINDS.map((kind) => ({
    kind,
    ofKind: connections.filter((c) => CONNECTION_KIND[c.type] === kind),
  })).filter((s) => s.ofKind.length > 0);

  return (
    <Flex vertical gap={24}>
      {sections.map(({ kind, ofKind }, i) => (
        <Flex key={kind} vertical gap={16}>
          {i > 0 && <Divider style={{ margin: '0 0 4px' }} />}
          <Typography.Title level={4} style={{ margin: 0 }}>
            {CONNECTION_KIND_LABELS[kind]}
          </Typography.Title>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
              gap: 16,
            }}
          >
            {ofKind.map((connection) => (
              <ConnectionCard
                key={connection.id}
                connection={connection}
                actions={actions}
                health={health[connection.id] ?? 'idle'}
              />
            ))}
          </div>
        </Flex>
      ))}
    </Flex>
  );
}

/** Health badge per connectivity state (the bulk health view's signal). */
function HealthBadge({ health }: { health: HealthState }) {
  switch (health) {
    case 'testing':
      return <Badge status="processing" text="testing…" />;
    case 'ok':
      return <Badge status="success" text="healthy" />;
    case 'failed':
      return <Badge status="error" text="unreachable" />;
    case 'idle':
      return null;
  }
}

function ConnectionCard({
  connection,
  actions,
  health,
}: {
  connection: Connection;
  actions: ConnectionActions;
  health: HealthState;
}) {
  const confirmDelete = useConfirmDelete();

  const onDelete = () =>
    confirmDelete({
      label: connection.name,
      content: 'This removes the connection and its stored credential.',
      onDelete: async () => {
        await deleteConnection(connection.id);
        actions.onClearHealth(connection.id);
      },
      onDone: actions.onChanged,
    });

  const menuItems = [
    { key: 'edit', label: 'Edit', onClick: () => actions.onEdit(connection) },
    { key: 'reauth', label: 'Re-authenticate', onClick: () => actions.onReauth(connection) },
    { type: 'divider' as const },
    { key: 'delete', label: 'Delete', danger: true, onClick: onDelete },
  ];

  const isOrchestration = CONNECTION_KIND[connection.type] === 'orchestration';

  return (
    <Card size="small" className="dq-card--interactive" styles={{ body: { padding: 20 } }}>
      <Flex vertical gap={14}>
        {/* Avatar left; live health badge + actions menu top-right. */}
        <Flex justify="space-between" align="flex-start">
          <ConnectionTypeAvatar type={connection.type} size={44} />
          <Flex gap={4} align="center">
            <HealthBadge health={health} />
            <Dropdown menu={{ items: menuItems }} trigger={['click']}>
              <Button
                size="small"
                type="text"
                icon={<MoreOutlined />}
                aria-label={`${connection.name} actions`}
              />
            </Dropdown>
          </Flex>
        </Flex>

        {/* Identity: name + type (· Orchestration for providers). */}
        <Flex vertical gap={2} style={{ minWidth: 0 }}>
          <Typography.Text strong ellipsis style={{ fontSize: 15 }}>
            {connection.name}
          </Typography.Text>
          <Typography.Text type="secondary" style={{ fontSize: 13 }}>
            {CONNECTION_TYPE_LABELS[connection.type]}
            {isOrchestration ? ' · Orchestration' : ''}
          </Typography.Text>
        </Flex>

        {/* Footer: env + credential state on the left, Test on the right. */}
        <Flex justify="space-between" align="center" gap={8}>
          <Flex gap={8} align="center" wrap style={{ minWidth: 0 }}>
            <Tag color={ENV_COLORS[connection.env]} style={{ marginInlineEnd: 0 }}>
              {envLabel(connection.env)}
            </Tag>
            {connection.has_secret ? (
              <Badge status="success" text="credential set" />
            ) : (
              <Badge status="warning" text="no credential" />
            )}
            {/* A failing poll is a fact about the connection now, not a log line (#828).
                Without this, an integration that has been dead for a week renders
                identically to a healthy one — which is how prod lineage rotted for six
                days behind an expired credential with nobody the wiser. The count is
                shown because "failing" and "failing since last Tuesday" are different
                problems. */}
            {(connection.consecutive_poll_failures ?? 0) > 0 && (
              <Tooltip
                title={
                  connection.last_poll_error
                    ? `Last error: ${connection.last_poll_error}`
                    : 'The scheduled poll for this connection is failing.'
                }
              >
                <Badge
                  status="error"
                  text={`poll failing (${connection.consecutive_poll_failures}×)`}
                />
              </Tooltip>
            )}
            {/* The same fact for a DATASOURCE connection (#954). Nothing polls one,
                so a dead credential used to be invisible here — it showed on the
                failing RUN, not on the connection that caused it, and diagnosing
                two dead prod Snowflake connections meant reading worker logs.
                Derived from runs, so it appears without anyone clicking Test. */}
            {(connection.consecutive_run_failures ?? 0) > 0 && (
              <Tooltip
                title={
                  connection.last_run_error
                    ? `Last run failed: ${connection.last_run_error}`
                    : 'Every recent suite run on this connection failed.'
                }
              >
                <Badge
                  status="error"
                  text={`runs failing (${connection.consecutive_run_failures}×)`}
                />
              </Tooltip>
            )}
          </Flex>
          <Button
            size="small"
            loading={health === 'testing'}
            onClick={() => actions.onTest(connection)}
          >
            Test
          </Button>
        </Flex>

        {health === 'failed' && (
          <Button
            type="link"
            size="small"
            style={{ padding: 0, height: 'auto', alignSelf: 'flex-start' }}
            onClick={() => actions.onReauth(connection)}
          >
            Re-authenticate
          </Button>
        )}
      </Flex>
    </Card>
  );
}

import { api } from './client';

/**
 * Connections API — the eight configurable connection types (CLAUDE.md §4).
 * ADF, Airflow + dbt are orchestration providers, not datasources, but they are
 * still `connections` rows and managed through the same CRUD surface.
 */

export const CONNECTION_TYPES = [
  'snowflake',
  'adls_gen2',
  's3',
  'unity_catalog',
  'iceberg',
  'adf',
  'airflow',
  'dbt',
] as const;
export type ConnectionType = (typeof CONNECTION_TYPES)[number];

/**
 * Datasource vs orchestration is the load-bearing distinction in DataQ
 * (CLAUDE.md §4): datasources are stores you write checks against; ADF/Airflow
 * are orchestration providers we monitor + trigger from, never queryable. This
 * map is the single source for that split — the add-connection picker and the
 * sectioned list both derive their groups from it (no hardcoded lists elsewhere).
 */
export const CONNECTION_KINDS = ['datasource', 'orchestration'] as const;
export type ConnectionKind = (typeof CONNECTION_KINDS)[number];

export const CONNECTION_KIND: Record<ConnectionType, ConnectionKind> = {
  snowflake: 'datasource',
  adls_gen2: 'datasource',
  s3: 'datasource',
  unity_catalog: 'datasource',
  iceberg: 'datasource',
  adf: 'orchestration',
  airflow: 'orchestration',
  dbt: 'orchestration',
};

export const CONNECTION_KIND_LABELS: Record<ConnectionKind, string> = {
  datasource: 'Data sources',
  orchestration: 'Orchestration',
};

/** Types of a given kind, in canonical CONNECTION_TYPES order. */
export const typesOfKind = (kind: ConnectionKind): ConnectionType[] =>
  CONNECTION_TYPES.filter((t) => CONNECTION_KIND[t] === kind);

export const DATASOURCE_TYPES = typesOfKind('datasource');
export const ORCHESTRATION_TYPES = typesOfKind('orchestration');

/**
 * Coarser datasource grouping for the Results datasource-type filter (ADR 0022):
 * the two flat-file types (ADLS Gen2 + S3) share a runner shape and read as one
 * "Flat file" choice, while Snowflake and Unity Catalog stand alone. Orchestration
 * types map to `null` — they're never queryable, so they never back a suite/run.
 */
export const DATASOURCE_CATEGORIES = ['snowflake', 'flatfile', 'unity_catalog', 'iceberg'] as const;
export type DatasourceCategory = (typeof DATASOURCE_CATEGORIES)[number];

export const DATASOURCE_CATEGORY: Record<ConnectionType, DatasourceCategory | null> = {
  snowflake: 'snowflake',
  adls_gen2: 'flatfile',
  s3: 'flatfile',
  unity_catalog: 'unity_catalog',
  iceberg: 'iceberg',
  adf: null,
  airflow: null,
  dbt: null,
};

export const DATASOURCE_CATEGORY_LABELS: Record<DatasourceCategory, string> = {
  snowflake: 'Snowflake',
  flatfile: 'Flat file',
  unity_catalog: 'Unity Catalog',
  iceberg: 'Apache Iceberg',
};

/**
 * Datasources GX can run a custom-SQL (`UnexpectedRowsExpectation`) query against
 * — mirrors the backend `custom_sql.SQL_QUERYABLE_TYPES` (ADR 0019). The custom-SQL
 * check category is offered only for these SQL-queryable types; flat files (ADLS /
 * S3) are DataFrame assets, not SQL, and the backend 422s custom-SQL on any other.
 */
export const SQL_QUERYABLE_TYPES: ConnectionType[] = ['snowflake', 'unity_catalog'];

export const isSqlQueryable = (type: ConnectionType): boolean => SQL_QUERYABLE_TYPES.includes(type);

/** The flat-file datasources — the only ones with a native per-object arrival
 *  time, so the only ones that can measure freshness without a column (#520). */
export const FILE_TYPES: ConnectionType[] = ['adls_gen2', 's3'];

export const isFileDatasource = (type: ConnectionType): boolean => FILE_TYPES.includes(type);

/**
 * Datasources whose runner can evaluate freshness/volume **monitors** — the SQL
 * datasources (in-warehouse aggregate), Iceberg (native `scan().count()` / a
 * column MAX, ADR 0030), and flat files (over the resolved batch, #520). Broader
 * than `SQL_QUERYABLE_TYPES`: neither Iceberg nor a flat file is SQL-queryable
 * (no custom-SQL). Mirrors the backend `check_service.MONITOR_CAPABLE_TYPES`
 * author gate.
 */
export const MONITOR_CAPABLE_TYPES: ConnectionType[] = [
  'snowflake',
  'unity_catalog',
  'iceberg',
  ...FILE_TYPES,
];

export const supportsMonitors = (type: ConnectionType): boolean =>
  MONITOR_CAPABLE_TYPES.includes(type);

export const CONNECTION_ENVS = ['dev', 'qa', 'uat', 'prod'] as const;
export type ConnectionEnv = (typeof CONNECTION_ENVS)[number];

/** Display label for an env (single source for the list page + the drawer). */
export const envLabel = (env: ConnectionEnv): string => env.toUpperCase();

/** Tag color per env — shared by every page that renders an env badge. */
export const ENV_COLORS: Record<ConnectionEnv, string> = {
  dev: 'blue',
  qa: 'gold',
  uat: 'purple',
  prod: 'red',
};

/** Mirrors the backend `ConnectionRead` schema (secret is never returned). */
export interface Connection {
  id: string;
  name: string;
  type: ConnectionType;
  env: ConnectionEnv;
  config: Record<string, unknown>;
  has_secret: boolean;
  created_by: string;
  /** Poll health (#828) — orchestration connections only. A failing poll used to be
   *  visible ONLY in the logs, so a dead integration looked exactly like a healthy
   *  quiet one. `last_poll_error` is a classified reason, never raw exception text. */
  last_polled_at?: string | null;
  last_poll_error?: string | null;
  consecutive_poll_failures?: number;
  /** Run-derived health (#954) — DATASOURCE connections. Nothing polls a datasource,
   *  so a dead credential was invisible here until someone clicked Test: two prod
   *  Snowflake connections sat dead for weeks. Derived from `runs`, so it cannot
   *  disagree with them. `last_run_error` is already classified server-side (#605). */
  last_run_at?: string | null;
  last_run_error?: string | null;
  consecutive_run_failures?: number;
}

/** Human-readable labels for the connection types, for grouping + display. */
export const CONNECTION_TYPE_LABELS: Record<ConnectionType, string> = {
  snowflake: 'Snowflake',
  adls_gen2: 'ADLS Gen2',
  s3: 'AWS S3',
  unity_catalog: 'Unity Catalog',
  iceberg: 'Apache Iceberg',
  adf: 'Azure Data Factory',
  airflow: 'Airflow',
  dbt: 'dbt',
};

/**
 * The `name · type · ENV` label used by the connection-picker `Select` in the
 * suite create + import drawers. One definition so the format can't drift
 * between the two pickers.
 */
export const connectionOptionLabel = (c: Connection): string =>
  `${c.name} · ${CONNECTION_TYPE_LABELS[c.type]} · ${envLabel(c.env)}`;

export async function listConnections(params?: {
  type?: ConnectionType;
  env?: ConnectionEnv;
}): Promise<Connection[]> {
  const { data } = await api.get<Connection[]>('/connections', { params });
  return data;
}

/** Fetch one connection by id (e.g. to learn a suite's datasource type). */
export async function getConnection(id: string): Promise<Connection> {
  const { data } = await api.get<Connection>(`/connections/${id}`);
  return data;
}

/** Live connectivity test — a green result means the credential authenticates. */
export async function testConnection(id: string): Promise<{ ok: boolean }> {
  const { data } = await api.post<{ ok: boolean }>(`/connections/${id}/test`);
  return data;
}

/** Mirrors the backend `ConnectionCreate` schema (secret is write-only). */
export interface ConnectionCreate {
  name: string;
  type: ConnectionType;
  env: ConnectionEnv;
  config: Record<string, unknown>;
  secret?: string;
}

export async function createConnection(payload: ConnectionCreate): Promise<Connection> {
  const { data } = await api.post<Connection>('/connections', payload);
  return data;
}

/** Mirrors the backend `ConnectionUpdate` schema — type/env are immutable. */
export interface ConnectionUpdate {
  name?: string;
  config?: Record<string, unknown>;
  secret?: string;
}

export async function updateConnection(id: string, payload: ConnectionUpdate): Promise<Connection> {
  const { data } = await api.patch<Connection>(`/connections/${id}`, payload);
  return data;
}

export async function deleteConnection(id: string): Promise<void> {
  await api.delete(`/connections/${id}`);
}

/** Rotate the credential and verify it in one step (bad credential → error). */
export async function reauthConnection(id: string, secret: string): Promise<{ ok: boolean }> {
  const { data } = await api.post<{ ok: boolean }>(`/connections/${id}/reauth`, { secret });
  return data;
}

/**
 * Mirrors the backend `ConnectionVersionRead` — one immutable snapshot in a
 * connection's edit history (#654). Only the editable, non-secret fields are
 * versioned; no credential is ever present. `changed_by_name` is resolved
 * server-side (null for a system actor / removed user).
 */
export interface ConnectionVersion {
  version_no: number;
  name: string;
  type: ConnectionType;
  env: ConnectionEnv;
  config: Record<string, unknown>;
  changed_by: string | null;
  changed_by_name: string | null;
  created_at: string;
}

/** A connection's version history, newest first. */
export async function listConnectionVersions(id: string): Promise<ConnectionVersion[]> {
  const { data } = await api.get<ConnectionVersion[]>(`/connections/${id}/versions`);
  return data;
}

