    expect(mockRevoke).not.toHaveBeenCalled();

    const confirm = await within(document.body).findByRole('button', { name: 'Revoke' });
    await user.click(confirm);
    await waitFor(() => expect(mockRevoke).toHaveBeenCalledWith('k1'));
  }, 15000);

