40	/** Live connectivity state for a card — the health-page badge. */
41	type HealthState = 'idle' | 'testing' | 'ok' | 'failed';
42	
43	/** Per-card actions, threaded from the page so they can mutate shared state. */
44	interface ConnectionActions {
45	  onEdit: (connection: Connection) => void;
46	  onReauth: (connection: Connection) => void;
47	  onChanged: () => void;
48	  /** Run a connectivity test and reflect the result on the card's health badge. */
49	  onTest: (connection: Connection) => Promise<boolean>;
50	  /** Drop a connection's stale health entry (after delete / edit / re-auth). */
51	  onClearHealth: (id: string) => void;
52	}
