54	export function Connections() {
55	  const { message } = App.useApp();
56	  const navigate = useNavigate();
57	  const { state, reload } = useAsyncData(listConnections);
58	  const [reauthing, setReauthing] = useState<Connection | null>(null);
59	  // Per-connection live connectivity status (the bulk health view).
60	  const [health, setHealth] = useState<Record<string, HealthState>>({});
61	  const [testingAll, setTestingAll] = useState(false);
62	
63	  const testOne = useCallback(async (connection: Connection): Promise<boolean> => {
64	    setHealth((h) => ({ ...h, [connection.id]: 'testing' }));
65	    try {
66	      const { ok } = await testConnection(connection.id);
67	      setHealth((h) => ({ ...h, [connection.id]: ok ? 'ok' : 'failed' }));
68	      return ok;
69	    } catch {
70	      setHealth((h) => ({ ...h, [connection.id]: 'failed' }));
71	      return false;
72	    }
73	  }, []);
74	
75	  // Drop a stale health result when the connection changes underneath it —
76	  // after a re-auth, an edit, or a delete the prior pass/fail no longer holds,
77	  // so the badge returns to idle until re-tested (and the map can't leak).
78	  const clearHealth = useCallback((id: string) => {
79	    setHealth((h) =>
80	      id in h ? Object.fromEntries(Object.entries(h).filter(([key]) => key !== id)) : h,
81	    );
82	  }, []);
83	
84	  const connections = state.status === 'ok' ? state.data : [];
85	
86	  const testAll = async () => {
87	    setTestingAll(true);
88	    const results = await Promise.all(connections.map(testOne));
89	    setTestingAll(false);
90	    const failed = results.filter((ok) => !ok).length;
91	    if (failed === 0) message.success(`All ${results.length} connections healthy`);
92	    else message.warning(`${failed} of ${results.length} connections unreachable`);
93	  };
94	
