96	    // Editing is a dedicated page (create + edit pages replace the drawer, ADR 0022).
97	    onEdit: (connection) => navigate(`/connections/${connection.id}/edit`),
98	    onReauth: setReauthing,
99	    onChanged: reload,
100	    onTest: testOne,
101	    onClearHealth: clearHealth,
102	  };
103	
104	  return (
105	    <Page>
106	      <Flex justify="space-between" align="center" gap={12} wrap>
107	        <Typography.Title level={3} style={{ margin: 0 }}>
108	          Connections
109	        </Typography.Title>
110	        <Flex gap={8}>
111	          <Button loading={testingAll} disabled={connections.length === 0} onClick={testAll}>
112	            Test all
113	          </Button>
114	          <Button type="primary" onClick={() => navigate('/connections/new')}>
115	            Add connection
116	          </Button>
117	        </Flex>
118	      </Flex>
119	      <ConnectionsBody state={state} actions={actions} health={health} />
120	      <ReauthModal
121	        connection={reauthing}
122	        onClose={() => setReauthing(null)}
123	        onDone={() => {
124	          // Credential rotated → the old unreachable verdict no longer holds.
125	          if (reauthing) clearHealth(reauthing.id);
126	          setReauthing(null);
